syntax:
istream& seekg(pos_type pos); // Repositions the get pointer to the specified position within the stream
// or
istream& seekg(off_type off, ios_base::seekdir dir); // Repositions relative to a position specified by dir

code_example:
#include <iostream>
#include <fstream>
int main() {
    std::ifstream file("example.txt");
    if (!file) {
        std::cerr << "Failed to open file" << std::endl;
        return 1;
    }
    // Move to the 10th byte from the beginning
    file.seekg(10, std::ios::beg);
    if (file.fail()) {
        std::cerr << "seekg() failed" << std::endl;
        return 1;
    }
    std::string data;
    std::getline(file, data);
    std::cout << "Data from position 10: " << data << std::endl;
    return 0;
}
